# Logo matches the application's geometric PixelMark.
rects=[]
for k,color in enumerate(['#d2d0ca','#aaa9a2','#252523']):
 for y,row in enumerate(['0111','1000','1111','1000','0111']):
  for x,pixel in enumerate(row):
   if pixel=='1':rects.append(f'<rect x="{x+2*k}" y="{y+k}" width="1" height="1" fill="{color}"/>')
