for lang,c in content.items():
 url=ORIGIN+('/zh/' if lang=='zh' else '/');canonlang='zh-CN' if lang=='zh' else 'en'
 schema={'@context':'https://schema.org','@type':'SoftwareApplication','name':'Reeeead','operatingSystem':'macOS 14+','applicationCategory':'UtilitiesApplication','description':c['description'],'url':url,'codeRepository':GH,'license':'https://opensource.org/license/mit','softwareVersion':'0.4.0','offers':{'@type':'Offer','price':'0','priceCurrency':'USD','description':'Free app source; external speech API usage may incur provider charges.'}}
 faq=''.join(f'<details><summary>{html.escape(q)}<span aria-hidden="true">+</span></summary><p>{html.escape(a)}</p></details>' for q,a in c['faqs'])
 paragraphs=(['A little less noise.','A little more room to read.','One line at a time.'] if lang=='en' else ['少一点干扰。','多一点阅读的空间。','一行一行，慢慢来。'])
 sample=' '.join(paragraphs)
